/**
 * Invocable action used by the Submit_CCAR_For_Approval flow (called from the
 * "Submit for Approval" quick action on the header). For each Draft line passed in:
 * snapshots Country__r.Country_Access_Owner__c onto Approver__c, then submits the
 * line into the CCAR_Line_Approval approval process. Bulk-safe.
 */
public without sharing class LSOSubmitForApproval {

    public class Request {
        @InvocableVariable(label='Line Ids' required=true)
        public List<Id> lineIds;
    }

    public class Result {
        @InvocableVariable(label='Success')
        public Boolean success;

        @InvocableVariable(label='Message')
        public String message;
    }

    /**
     * Standard bulkified invocable pattern: the outer List<Request> is one entry per
     * flow interview (only relevant when this action fires from bulk/record-triggered
     * automation). The Ids to submit for a SINGLE interview must live on a collection
     * field nested inside Request - Flow can't bind a flow collection variable directly
     * to the action's top-level list parameter, regardless of that list's element type.
     */
    @InvocableMethod(
        label='Submit CCAR Lines For Approval'
        description='Snapshots each line\'s country approver onto Approver__c and submits the line for approval.'
    )
    public static List<Result> submitLines(List<Request> requests) {
        List<Result> results = new List<Result>();

        Set<Id> lineIds = new Set<Id>();
        if (requests != null) {
            for (Request r : requests) {
                if (r.lineIds != null) {
                    lineIds.addAll(r.lineIds);
                }
            }
        }

        if (lineIds.isEmpty()) {
            return results;
        }

        Map<Id, LSO_CCAR_Line__c> draftLines = new Map<Id, LSO_CCAR_Line__c>([
            SELECT Id, Country__r.Country_Access_Owner__c, Line_Status__c
            FROM LSO_CCAR_Line__c
            WHERE Id IN :lineIds
            AND Line_Status__c = 'Draft'
        ]);

        if (draftLines.isEmpty()) {
            return results;
        }

        List<LSO_CCAR_Line__c> toUpdate = new List<LSO_CCAR_Line__c>();
        for (LSO_CCAR_Line__c ln : draftLines.values()) {
            toUpdate.add(new LSO_CCAR_Line__c(
                Id = ln.Id,
                Approver__c = ln.Country__r.Country_Access_Owner__c
            ));
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        List<Approval.ProcessSubmitRequest> submissions = new List<Approval.ProcessSubmitRequest>();
        for (Id lineId : draftLines.keySet()) {
            Approval.ProcessSubmitRequest psr = new Approval.ProcessSubmitRequest();
            psr.setObjectId(lineId);
            psr.setSubmitterId(UserInfo.getUserId());
            submissions.add(psr);
        }

        List<Approval.ProcessResult> processResults = Approval.process(submissions, false);
        for (Approval.ProcessResult pr : processResults) {
            Result res = new Result();
            res.success = pr.isSuccess();
            if (pr.isSuccess()) {
                res.message = 'Submitted';
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : pr.getErrors()) {
                    messages.add(err.getMessage());
                }
                res.message = messages.isEmpty() ? 'Submission failed' : String.join(messages, '; ');
            }
            results.add(res);
        }

        return results;
    }
}
